// Generated by Omi.Java.Repository. Edits are overwritten on the next generation.

subprojects {
    apply(plugin = "java-library")

    // The generated code depends on nothing outside the JDK, so no repositories and
    // no dependencies are declared. A protocol builds with a bare Gradle and a JDK.
    extensions.configure<JavaPluginExtension> {
        toolchain {
            languageVersion = JavaLanguageVersion.of(17)
        }
        withSourcesJar()
        withJavadocJar()
    }

    tasks.withType<JavaCompile>().configureEach {
        options.encoding = "UTF-8"
        options.compilerArgs.addAll(listOf("-Xlint:all", "-Werror"))
    }

    tasks.withType<Javadoc>().configureEach {
        (options as StandardJavadocDocletOptions).addBooleanOption("Xdoclint:all", true)
    }
}
